  FT["PH-H1933"] = {"id":"PH-H1933","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2196_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Barrio Kiug-Ang, Municipality of Jasaan, Province of Misamis Oriental, to Luz","orig":"An Act Changing the Name of Barrio Kiug-Ang, Municipality of Jasaan, Province of Misamis Oriental, to Luz"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2196","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-05-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2196_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1933-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Barrio Kiug-ang in the Municipality of Jasaan, Province of Misamis Oriental is changed to Luz, to wit: Barrio Luz, Municipality of Jasaan, Province to Misamis Oriental."}},{"id":"PH-H1933-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 7, 1959."}}],"pack":"ph-p27"};
  FT["PH-H1934"] = {"id":"PH-H1934","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2197_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Tingloy市","en":"An Act Creating the Barrio of San Isidro in the Municipality of Tingloy, Province of Batangas","orig":"An Act Creating the Barrio of San Isidro in the Municipality of Tingloy, Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2197","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-05-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2197_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1934-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Banalo, Camastilisan, Pook, Pinagiluhan and Look in the barrio of Papaya, and the sitios of Nangcaan and Bucal in the barrio of Pisa, all in the Municipality of Tingloy, Province of Batangas, are separated from the said barrios, and are constituted into a distinct and independent barrio of said municipality to be known as the barrio of San Isidro."}},{"id":"PH-H1934-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 7, 1959."}}],"pack":"ph-p27"};
