  FT["PH-H1955"] = {"id":"PH-H1955","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2218_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Quinapundan市","en":"An Act Creating Certain Barrios in the Municipality of Quinapundan, Province of Samar","orig":"An Act Creating Certain Barrios in the Municipality of Quinapundan, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2218","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-05-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2218_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1955-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Palactad, Pana-ogan, Loro nga Diyo and Anislag in the Municipality of Quinapundan, Province of Samar, are converted into barrios of said municipality to be known as the barrios of Mons. Guimbaolibot, Victor Terencio, Mons. Joel and Ramon Magsaysay, respectively."}},{"id":"PH-H1955-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 16, 1959."}}],"pack":"ph-p27"};
