  FT["PH-H1958"] = {"id":"PH-H1958","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2221_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Murcia市","en":"An Act Creating the Barrio of Manyaya in the Municipality of Murcia, Province of Negros Occidental","orig":"An Act Creating the Barrio of Manyaya in the Municipality of Murcia, Province of Negros Occidental"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2221","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-05-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2221_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1958-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Manyaya in the barrio of Sta. Rosa, Municipality of Murcia, Province of Negros Occidental, is separated from said barrio and converted into a distinct and independent barrio of said municipality to be known as the barrio of Manyaya.\nThe boundary of the proposed barrio of Manyaya and the barrio of Sta. Rosa, Municipality of Murcia, Province of Negros Occidental, shall be the Puncian River."}},{"id":"PH-H1958-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 16, 1959."}}],"pack":"ph-p27"};
  FT["PH-H1959"] = {"id":"PH-H1959","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2222_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing to Marilag the Name of Barrio Pinagkaanuran in the Municipality of Rosario, Province of Batangas","orig":"An Act Changing to Marilag the Name of Barrio Pinagkaanuran in the Municipality of Rosario, Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2222","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-05-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2222_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1959-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Barrio Pinagkaanuran in the Municipality of Rosario, Province of Batangas, is hereby changed to Marilag."}},{"id":"PH-H1959-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 16, 1959."}}],"pack":"ph-p27"};
